void RTCAlarm_IRQHandler(void)
{
  if (RTC_GetITStatus(RTC_IT_ALR) != RESET)
  {
    RTC_ClearITPendingBit(RTC_IT_ALR);
    RTC_WaitForLastTask();
    /* 定时任务 */
  }
  EXTI_ClearITPendingBit(EXTI_Line17);  /* 闹钟同时接到 EXTI17，若开了 EXTI 中断要一起清 */
}

/* 标准写法：等待 -> 进配置 -> 写 -> 出配置 -> 等待 */
RTC_WaitForLastTask();
RTC_EnterConfigMode();

/* 配置模式下写寄存器 */
RTC_SetCounter(0);          /* 计数器清零 */
RTC_SetAlarm(3600);         /* 1 小时后闹钟 */

RTC_ExitConfigMode();
RTC_WaitForLastTask();

RTC_WaitForLastTask();
RTC_EnterConfigMode();
RTC_SetPrescaler(32767);      /* LSE 32768Hz 分频成 1Hz */
RTC_SetCounter(0);
RTC_ExitConfigMode();
RTC_WaitForLastTask();        /* 退出后必须等，才能安全地读计数器 */

/* 读取当前时间（秒） */
uint32_t ts = RTC_GetCounter();

/* SPL 没有日历换算，需要自己算 */
uint16_t hour = (ts % 86400) / 3600;
uint16_t min  = (ts % 3600) / 60;
uint16_t sec  = ts % 60;

#define RTC_BASE_2024  1704067200u   /* 2024-01-01 00:00:00 UTC */

RTC_WaitForLastTask();
RTC_EnterConfigMode();
RTC_SetCounter(RTC_BASE_2024);   /* 设定时间基准 */
RTC_SetAlarm(RTC_BASE_2024 + 60);/* 基准后 60 秒闹钟 */
RTC_ExitConfigMode();
RTC_WaitForLastTask();

/* 读回校验 */
if (RTC_GetCounter() >= RTC_BASE_2024) { /* 设定成功 */ }

/* 首次初始化 RTC：LSE 32768Hz 分频为 1Hz */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);
RCC_LSEConfig(RCC_LSE_ON);
while (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET) { }
RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);
RCC_RTCCLKCmd(ENABLE);

RTC_WaitForSynchro();
RTC_WaitForLastTask();
RTC_EnterConfigMode();
RTC_SetPrescaler(32767);   /* 32768 / (32767+1) = 1Hz */
RTC_ExitConfigMode();
RTC_WaitForLastTask();

/* 10 秒后闹钟唤醒一次（低功耗定时上报场景） */
RTC_WaitForLastTask();
RTC_EnterConfigMode();
RTC_SetAlarm(RTC_GetCounter() + 10);   /* 必须大于当前计数值 */
RTC_ExitConfigMode();
RTC_WaitForLastTask();

/* 周期闹钟：在中断里重新装下一次 */
void RTCAlarm_IRQHandler(void)
{
  if (RTC_GetITStatus(RTC_IT_ALR) != RESET)
  {
    RTC_ClearITPendingBit(RTC_IT_ALR);
    RTC_WaitForLastTask();

    RTC_WaitForLastTask();
    RTC_EnterConfigMode();
    RTC_SetAlarm(RTC_GetCounter() + 10);  /* 装下一次，间隔 10s */
    RTC_ExitConfigMode();
    RTC_WaitForLastTask();
  }
  EXTI_ClearITPendingBit(EXTI_Line17);
}

/* 用 DIV 算亚秒精度：LSE 32768Hz，分频 PRL=32767 时 1Hz */
uint32_t sec = RTC_GetCounter();
uint32_t div = RTC_GetDivider();

/* 小数秒比例：div 从 PRL+1 递减到 0 */
float frac = 1.0f - (float)div / 32768.0f;

/* 判活：连续两次读 DIV 应不同，若相同说明 RTC 没在走 */

/* 修改 RTC 寄存器的推荐模板 */
RTC_WaitForLastTask();     /* 1. 等上一次写完成 */
RTC_EnterConfigMode();     /* 2. 进入配置模式 */
RTC_SetCounter(0);         /* 3. 写寄存器 */
RTC_ExitConfigMode();      /* 4. 退出配置模式 */
RTC_WaitForLastTask();     /* 5. 再等本次写完成（关键，别省） */

/* 之后读计数器才是可靠值 */
uint32_t sec = RTC_GetCounter();

/* 首次配置 RTC 时：等 LSE 起振 -> 选时钟源 -> 使能 -> 等同步 -> 配置 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

RCC_LSEConfig(RCC_LSE_ON);
while (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET) { }  /* 等晶振起振 */

RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);
RCC_RTCCLKCmd(ENABLE);

RTC_WaitForSynchro();     /* 关键：不等 RSF 就读寄存器会读到无效值 */
RTC_WaitForLastTask();

RTC_EnterConfigMode();
RTC_SetPrescaler(32767);  /* 32768/(32767+1) = 1Hz */
RTC_SetCounter(0);
RTC_ExitConfigMode();
RTC_WaitForLastTask();

/* 轮询方式等待闹钟到达 */
while (RTC_GetFlagStatus(RTC_FLAG_ALR) == RESET)
{
  /* 等待中，可以顺便做点别的事 */
}
RTC_ClearFlag(RTC_FLAG_ALR);
RTC_WaitForLastTask();

/* 检查 RTC 是否已完成同步 */
if (RTC_GetFlagStatus(RTC_FLAG_RSF) == RESET)
{
  RTC_WaitForSynchro();
}

/* 清掉闹钟和秒标志 */
RTC_ClearFlag(RTC_FLAG_ALR | RTC_FLAG_SEC);
RTC_WaitForLastTask();

/* 轮询秒标志的标准写法 */
while (1)
{
  if (RTC_GetFlagStatus(RTC_FLAG_SEC) != RESET)
  {
    RTC_ClearFlag(RTC_FLAG_SEC);
    RTC_WaitForLastTask();
    /* 每秒执行一次的任务 */
  }
}

void RTCAlarm_IRQHandler(void)
{
  if (RTC_GetITStatus(RTC_IT_ALR) != RESET)
  {
    RTC_ClearITPendingBit(RTC_IT_ALR);
    RTC_WaitForLastTask();
    /* 处理闹钟事件 */
  }
}

void RTC_IRQHandler(void)
{
  /* 秒中断与闹钟中断共用同一个处理函数 */
  if (RTC_GetITStatus(RTC_IT_SEC) != RESET)
  {
    RTC_ClearITPendingBit(RTC_IT_SEC);
    RTC_WaitForLastTask();
  }
  if (RTC_GetITStatus(RTC_IT_ALR) != RESET)
  {
    RTC_ClearITPendingBit(RTC_IT_ALR);
    RTC_WaitForLastTask();
  }
}
